# Let's look at typical weight ranges for fc - what's "normal" for a strong feature-class connection?
fc_w = W['fc.weight']
print("All fc weights > 0.5:")
for i in range(10):
    for j in range(64):
        w = fc_w[i, j].item()
        if w > 0.5:
            print(f"  Class {i} ({CLASSES[i]}), Feature {j}: {w:.4f}")

print("\nAll fc weights < -0.5:")
for i in range(10):
    for j in range(64):
        w = fc_w[i, j].item()
        if w < -0.5:
            print(f"  Class {i} ({CLASSES[i]}), Feature {j}: {w:.4f}")

# Also check the distribution of weights
print(f"\nFC weight stats: mean={fc_w.mean():.4f}, std={fc_w.std():.4f}")
print(f"  Max: {fc_w.max():.4f}, Min: {fc_w.min():.4f}")
print(f"  95th percentile: {fc_w.abs().kthvalue(int(0.95 * fc_w.numel())).values.item():.4f}")
print(f"  99th percentile: {fc_w.abs().kthvalue(int(0.99 * fc_w.numel())).values.item():.4f}")
